# -*- coding: utf-8 -*-
"""Extract text from two Shijuanbao PDFs for diff."""
from pathlib import Path
from pypdf import PdfReader

BASE = Path(r"C:\Users\Stark8964911\Downloads")
FILES = [
    BASE / "试卷宝-数学五年级下学期试卷.pdf",
    BASE / "试卷宝-数学五年级下学期试卷1.pdf",
]


def extract_all(reader: PdfReader) -> str:
    parts: list[str] = []
    for page in reader.pages:
        parts.append(page.extract_text() or "")
    return "\n".join(parts)


def main() -> None:
    texts: dict[str, str] = {}
    for p in FILES:
        if not p.exists():
            print(f"MISSING: {p}")
            continue
        r = PdfReader(str(p))
        texts[p.name] = extract_all(r)
        print(f"OK {p.name} pages={len(r.pages)} chars={len(texts[p.name])}")

    if len(texts) != 2:
        return

    names = list(texts.keys())
    a, b = names[0], names[1]
    ta, tb = texts[a], texts[b]

    # Normalize whitespace for line-level diff
    def norm(s: str) -> str:
        lines = [ln.strip() for ln in s.splitlines()]
        return "\n".join(ln for ln in lines if ln)

    na, nb = norm(ta), norm(tb)
    if na == nb:
        print("\nTEXT (normalized): IDENTICAL")
        return

    la, lb = na.split("\n"), nb.split("\n")
    from difflib import unified_diff

    diff = list(
        unified_diff(la, lb, fromfile=a, tofile=b, lineterm="", n=2)
    )
    print("\n--- unified_diff (first 200 lines) ---")
    for i, line in enumerate(diff[:200]):
        print(line)
    if len(diff) > 200:
        print(f"... ({len(diff) - 200} more diff lines)")

    # Quick stats
    set_a, set_b = set(la), set(lb)
    only_a = sorted(set_a - set_b)
    only_b = sorted(set_b - set_a)
    print(f"\nLines only in {a}: {len(only_a)}")
    for ln in only_a[:30]:
        print("  +", ln[:120])
    if len(only_a) > 30:
        print(f"  ... and {len(only_a) - 30} more")
    print(f"\nLines only in {b}: {len(only_b)}")
    for ln in only_b[:30]:
        print("  +", ln[:120])
    if len(only_b) > 30:
        print(f"  ... and {len(only_b) - 30} more")


if __name__ == "__main__":
    main()
